from pysat.solvers import Glucose3
from itertools import combinations
import time

n_golfers = 18
n_groups = 6
n_size = 3
n_weeks = 7

def var(w, p, g):
    return w * n_golfers * n_groups + p * n_groups + g + 1

clauses = []

# 1. Each golfer is in exactly one group per week
for w in range(n_weeks):
    for p in range(n_golfers):
        lits = [var(w, p, g) for g in range(n_groups)]
        clauses.append(lits)
        for g1, g2 in combinations(range(n_groups), 2):
            clauses.append([-var(w, p, g1), -var(w, p, g2)])

# 2. Each group has at most n_size members per week
for w in range(n_weeks):
    for g in range(n_groups):
        for combo in combinations(range(n_golfers), n_size + 1):
            clauses.append([-var(w, combo[i], g) for i in range(n_size + 1)])

# 3. No pair in same group more than once
for p1, p2 in combinations(range(n_golfers), 2):
    for w1, w2 in combinations(range(n_weeks), 2):
        for g in range(n_groups):
            clauses.append([-var(w1, p1, g), -var(w1, p2, g), -var(w2, p1, g), -var(w2, p2, g)])

# Symmetry breaking: fix week 0
for p in range(n_golfers):
    g = p // n_size
    clauses.append([var(0, p, g)])

print(f"Total clauses: {len(clauses)}, Variables: {n_golfers * n_groups * n_weeks}")

solver = Glucose3()
for cl in clauses:
    solver.add_clause(cl)

print("Solving...")
t = time.time()
result = solver.solve()
print(f"Result: {result}, Time: {time.time()-t:.2f}s")

if result:
    model = solver.get_model()
    schedule = [[None]*n_golfers for _ in range(n_weeks)]
    for w in range(n_weeks):
        for p in range(n_golfers):
            for g in range(n_groups):
                if model[var(w,p,g)-1] > 0:
                    schedule[w][p] = g
    print("Schedule found!")
    for w in range(n_weeks):
        print(f"Week {w}: {schedule[w]}")
